for name,(valid,available,provenance,content) in records.items():
 text=f'# {name[:-3].replace("_"," ").title()}\n\n**Claimed event date:** {valid}\n**Available to this fictional board archive:** {available}\n**Provenance:** {provenance}\n\n{content}'
 (A/name).write_text(text)
 if name in pre:(T/name).write_text(text)
